-- Keeps public.complexes in sync with app IDs (required for sightings.complex_id FK).
-- Run in Supabase → SQL Editor. Regenerate: node scripts/generate-complexes.mjs

on conflict (id) do update set
  name = excluded.name,
  address = excluded.address,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  visitor_time_limit_minutes = excluded.visitor_time_limit_minutes,
  booting_company = excluded.booting_company,
  signage_quality = excluded.signage_quality,
  risk_level = excluded.risk_level,
  notes = excluded.notes;